INSERT INTO collection_pages VALUES('c805c7e6e573b2b21adf6a5c13750bef859552716f1dbe021c89fb4896cbf634','7cd15b65dd6f743e390698f5575d46f438a200cd80316f6c25ce3f3f1f96ea93','{"hasNext":false,"items":[{"author":{"account":{"login":"IfeanyiXtopher","providerType":"User"},"email":"nwagbaraxtopher@gmail.com","name":"ifeanyixtopher"},"authoredDate":"2026-07-19T12:37:04Z","committedDate":"2026-07-19T12:37:04Z","committer":{"account":{"login":"IfeanyiXtopher","providerType":"User"},"email":"nwagbaraxtopher@gmail.com","name":"ifeanyixtopher"},"observedAt":"2026-10-08T23:49:29.937Z","repositoryId":1305311995,"sha":"fe4cb61d84f4b3ac1e847f980bd6872143ff5aa8"}],"observedAt":"2026-10-08T23:49:29.937Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/95752682?v=4","events_url":"https://api.github.com/users/IfeanyiXtopher/events{/privacy}","followers_url":"https://api.github.com/users/IfeanyiXtopher/followers","following_url":"https://api.github.com/users/IfeanyiXtopher/following{/other_user}","gists_url":"https://api.github.com/users/IfeanyiXtopher/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/IfeanyiXtopher","id":95752682,"login":"IfeanyiXtopher","node_id":"U_kgDOBbUR6g","organizations_url":"https://api.github.com/users/IfeanyiXtopher/orgs","received_events_url":"https://api.github.com/users/IfeanyiXtopher/received_events","repos_url":"https://api.github.com/users/IfeanyiXtopher/repos","site_admin":false,"starred_url":"https://api.github.com/users/IfeanyiXtopher/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/IfeanyiXtopher/subscriptions","type":"User","url":"https://api.github.com/users/IfeanyiXtopher","user_view_type":"public"},"comments_url":"https://api.github.com/repos/IfeanyiXtopher/SalesPilot/commits/fe4cb61d84f4b3ac1e847f980bd6872143ff5aa8/comments","commit":{"author":{"date":"2026-07-19T12:37:04Z","email":"nwagbaraxtopher@gmail.com","name":"ifeanyixtopher"},"comment_count":0,"committer":{"date":"2026-07-19T12:37:04Z","email":"nwagbaraxtopher@gmail.com","name":"ifeanyixtopher"},"message":"Initial project scaffold: FastAPI structure, full data model, first migration\n\nPhase 0/1 of MILESTONES.md: standard FastAPI project layout, pydantic-settings\nconfig, structured logging, and a 29-table multi-tenant Postgres schema\n(SQLAlchemy 2.0 typed models) across CRM core, targeting/signals, agent\nexecution/RAG, and delivery/CRM-sync domains.\n\nApplied and verified end-to-end against a real local Postgres instance:\nrow-level security on all 22 tenant-scoped tables, a least-privilege runtime\nrole separate from the migration/owner role (a superuser or table owner\nbypasses RLS by default in Postgres regardless of FORCE ROW LEVEL SECURITY),\nand a cross-tenant isolation test proving tenant B genuinely cannot read\ntenant A''s rows even via raw SQL.\n\nCo-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>","tree":{"sha":"6f02d9108c17230f41a5b3deb40953d144688869","url":"https://api.github.com/repos/IfeanyiXtopher/SalesPilot/git/trees/6f02d9108c17230f41a5b3deb40953d144688869"},"url":"https://api.github.com/repos/IfeanyiXtopher/SalesPilot/git/commits/fe4cb61d84f4b3ac1e847f980bd6872143ff5aa8","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/95752682?v=4","events_url":"https://api.github.com/users/IfeanyiXtopher/events{/privacy}","followers_url":"https://api.github.com/users/IfeanyiXtopher/followers","following_url":"https://api.github.com/users/IfeanyiXtopher/following{/other_user}","gists_url":"https://api.github.com/users/IfeanyiXtopher/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/IfeanyiXtopher","id":95752682,"login":"IfeanyiXtopher","node_id":"U_kgDOBbUR6g","organizations_url":"https://api.github.com/users/IfeanyiXtopher/orgs","received_events_url":"https://api.github.com/users/IfeanyiXtopher/received_events","repos_url":"https://api