INSERT INTO collection_pages VALUES('a3df28363f4c1743a2764a8dde5cda9effe1584af58cf0bd20b77dc6f73d95a9','440c7b96330f82ea792ed99c9efc54d3bf33383d4c7ad0e512fe788a290c403b','{"hasNext":false,"items":[{"author":{"account":null,"email":"yyle88@example.com","name":"yyle88"},"authoredDate":"2026-07-20T14:45:32Z","committedDate":"2026-07-20T14:45:32Z","committer":{"account":null,"email":"yyle88@example.com","name":"yyle88"},"observedAt":"2026-10-08T23:49:47.753Z","repositoryId":1305857551,"sha":"f74f397dd4a38a5d6761d57a1f425d3bc75bf0fd"},{"author":{"account":null,"email":"yyle88@example.com","name":"yyle88"},"authoredDate":"2026-07-19T14:44:30Z","committedDate":"2026-07-19T16:22:55Z","committer":{"account":null,"email":"yyle88@example.com","name":"yyle88"},"observedAt":"2026-10-08T23:49:47.753Z","repositoryId":1305857551,"sha":"d1ece34e3cfc4405dfb0150b12c341b72491593c"}],"observedAt":"2026-10-08T23:49:47.753Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/commits/f74f397dd4a38a5d6761d57a1f425d3bc75bf0fd/comments","commit":{"author":{"date":"2026-07-20T14:45:32Z","email":"yyle88@example.com","name":"yyle88"},"comment_count":0,"committer":{"date":"2026-07-20T14:45:32Z","email":"yyle88@example.com","name":"yyle88"},"message":"cut the 0.0.1 release\n\nHardens the sub-app CSS injection, adds vitest coverage, and aligns the\nREADME template blocks with the ecosystem standard.\n\nCo-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>","tree":{"sha":"f38ff84216c973c5bed0dbf000e64aa034bd1c9d","url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/git/trees/f38ff84216c973c5bed0dbf000e64aa034bd1c9d"},"url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/git/commits/f74f397dd4a38a5d6761d57a1f425d3bc75bf0fd","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/yylego/qiankun-vite-style-patch/commit/f74f397dd4a38a5d6761d57a1f425d3bc75bf0fd","node_id":"C_kwDOTdXOD9oAKGY3NGYzOTdkZDRhMzhhNWQ2NzYxZDU3YTFmNDI1ZDNiYzc1YmYwZmQ","parents":[{"html_url":"https://github.com/yylego/qiankun-vite-style-patch/commit/d1ece34e3cfc4405dfb0150b12c341b72491593c","sha":"d1ece34e3cfc4405dfb0150b12c341b72491593c","url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/commits/d1ece34e3cfc4405dfb0150b12c341b72491593c"}],"sha":"f74f397dd4a38a5d6761d57a1f425d3bc75bf0fd","url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/commits/f74f397dd4a38a5d6761d57a1f425d3bc75bf0fd"},{"author":null,"comments_url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/commits/d1ece34e3cfc4405dfb0150b12c341b72491593c/comments","commit":{"author":{"date":"2026-07-19T14:44:30Z","email":"yyle88@example.com","name":"yyle88"},"comment_count":0,"committer":{"date":"2026-07-19T16:22:55Z","email":"yyle88@example.com","name":"yyle88"},"message":"add qiankun-vite-style-patch package\n\nA compact package that fixes the production blank-screen /\nmissing-styles bug when qiankun 2.x mounts a Vite-built sub-app: it\nfetches the sub-app HTML page, picks out each stylesheet <link>,\ninjects the sheets into the main document head, and cleans them up on\na route change. It augments vite-plugin-qiankun, which covers the\nJS / lifecycle side but not this CSS injection.\n\nRobustness baked in:\n- the base path gains a trailing slash first, so a hash-free href\n  resolves inside the sub-app base and does not 404 at the main app root\n- concurrent mounts share one in-flight run; a fast route switch tags\n  the run stale and discards its late sheets\n- failed sheets get pruned from the head, and no broken node stays\n- injectSubAppStyles does not throw; it hands back\n  { injected, found, failed, cause } so app code can spot a broken sub-app\n\nTooling: a tsup build emitting ESM+CJS plus types, 16 vitest cases in a\nDOM sandbox, and a CI matrix across node 18/20/22. Scoped @yylego,\nEN + ZH README, version 0.0.0 as the starting skeleton.\n\nCo-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>","tree":{"sha":"99669883b27b3478bb65b12122357ad325ae2bc7","url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/git/trees/99669883b27b3478bb65b12122357ad325ae2bc7"},"url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/git/commits/d1ece34e3cfc4405dfb0150b12c341b72491593c","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/yylego/qiankun-vite-style-patch/commit/d1ece34e3cfc4405dfb0150b12c341b72491593c","node_id":"C_kwDOTdXOD9oAKGQxZWNlMzRlM2NmYzQ0MDVkZmIwMTUwYjEyYzM0MWI3MjQ5MTU5M2M","parents":[],"sha":"d1ece34e3cfc4405dfb0150b12c341b72491593c","url":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/commits/d1ece34e3cfc4405dfb0150b12c341b72491593c"}],"requestUrl":"https://api.github.com/repos/yylego/qiankun-vite-style-patch/commits?per_page=100&page=1&sha=f74f397dd4a38a5d6761d57a1f425d3bc75bf0fd&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A01%3A23.637Z"}');
